            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        // For each painting, find smallest frame that fits
        List<Integer> values = new ArrayList<>();
        for (int[] p : paintings) {
            int size = p[0];
            int value = p[1];
            int idx = lowerBound(C, size);
            if (idx == M) continue; // no frame fits
            values.add(value);
        }

        // LIS on values (non-decreasing)
        int[] dp = new int[values.size()];
        int len = 0;
        for (int v : values) {
            int pos = upperBound(dp, len, v);
            dp[pos] = v;
            if (pos == len) len++;
        }

        System.out.println(len);
    }

    // first index where arr[idx] >= key
    static int lowerBound(int[] arr, int key) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // first index where arr[idx] > key, within first 'len' elements
    static int upperBound(int[] arr, int len, int key) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] <= key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
