public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Painting {
        long s, v;
        Painting(long s, long v) {
            this.s = s;
            this.v = v;
        }
    }

    static int N, M;
    static Painting[] paintings;
    static long[] caps;

    static boolean can(int k) {
        if (k == 0) return true;
        int start = M - k; // 0-based index in sorted caps
        int cnt = 0;
        for (Painting p : paintings) {
            if (p.s <= caps[start + cnt]) {
                cnt++;
                if (cnt == k) return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        M = fs.nextInt();

        paintings = new Painting[N];
        for (int i = 0; i < N; i++) {
            long s = fs.nextLong();
            long v = fs.nextLong();
            paintings[i] = new Painting(s, v);
        }

        caps = new long[M];
        for (int i = 0; i < M; i++) caps[i] = fs.nextLong();

        Arrays.sort(caps);
        Arrays.sort(paintings, (a, b) -> {
            if (a.v != b.v) return Long.compare(a.v, b.v);
            return Long.compare(a.s, b.s);
        });

        int lo = 0, hi = Math.min(N, M);
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (can(mid)) lo = mid;
            else hi = mid - 1;
        }

        System.out.println(lo);
    }
}

